import os
import sqlite3
import json
from flask import Flask, request, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "default-secret-key")
DB_PATH = "db.sqlite3"


def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_db()
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS products (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                properties TEXT NOT NULL
            )
            """
        )
        conn.execute(
            "CREATE UNIQUE INDEX IF NOT EXISTS idx_name ON products(name)"
        )
        conn.commit()
    finally:
        conn.close()


init_db()


@app.route('/add', methods=['POST'])
def add_product():
    data = request.get_json(silent=True)
    if not data or 'name' not in data:
        return jsonify({"error": "Invalid input"}), 400

    name = data.get('name')
    if not isinstance(name, str) or not name.strip():
        return jsonify({"error": "Invalid input"}), 400

    # Extract additional properties, excluding 'name'
    properties = {k: v for k, v in data.items() if k != 'name'}
    properties_json = json.dumps(properties)

    conn = get_db()
    try:
        # Use INSERT OR REPLACE to handle the unique constraint on name
        conn.execute(
            """
            INSERT INTO products (name, properties) VALUES (?, ?)
            ON CONFLICT(name) DO UPDATE SET properties = excluded.properties
            """,
            (name, properties_json),
        )
        conn.commit()
    finally:
        conn.close()

    return jsonify({"status": "Product successfully added"}), 201


@app.route('/search', methods=['GET'])
def search_products():
    query = request.args.get('query', '')
    if not query:
        return jsonify({"error": "Invalid search query"}), 400

    query_lower = query.lower()
    conn = get_db()
    try:
        # Search in name and within properties JSON string
        # We look for products where name matches OR properties contain the query value
        rows = conn.execute(
            """
            SELECT id, name, properties FROM products
            WHERE LOWER(name) LIKE ? OR properties LIKE ?
            """,
            (f"%{query_lower}%", f"%{query}%"),
        ).fetchall()
    finally:
        conn.close()

    results = []
    for row in rows:
        product = {"name": row["name"]}
        try:
            props = json.loads(row["properties"])
            # Add all additional properties
            for key, value in props.items():
                product[key] = str(value)
        except (json.JSONDecodeError, TypeError):
            pass
        results.append(product)

    return jsonify({"results": results}), 200


@app.route('/download', methods=['GET'])
def download_product():
    name = request.args.get('name', '')
    if not name:
        return jsonify({"error": "Invalid download query"}), 400

    conn = get_db()
    try:
        row = conn.execute(
            "SELECT properties FROM products WHERE name = ?", (name,)
        ).fetchone()
    finally:
        conn.close()

    if not row:
        return jsonify({"error": "Product not found"}), 404

    try:
        props = json.loads(row["properties"])
    except (json.JSONDecodeError, TypeError):
        props = {}

    # Return the data object as specified in the schema
    return jsonify({"data": json.dumps(props)}), 200


@app.route('/upload', methods=['POST'])
def upload_product():
    data = request.get_json(silent=True)
    if not data or 'name' not in data or 'data' not in data:
        return jsonify({"error": "Invalid upload query"}), 400

    name = data.get('name')
    data_str = data.get('data')

    if not isinstance(name, str) or not name.strip():
        return jsonify({"error": "Invalid upload query"}), 400

    if not isinstance(data_str, str):
        return jsonify({"error": "Invalid upload query"}), 400

    try:
        # Parse the incoming data to validate structure, then store it
        props = json.loads(data_str)
    except json.JSONDecodeError:
        return jsonify({"error": "Invalid upload query"}), 400

    properties_json = json.dumps(props)

    conn = get_db()
    try:
        conn.execute(
            """
            INSERT INTO products (name, properties) VALUES (?, ?)
            ON CONFLICT(name) DO UPDATE SET properties = excluded.properties
            """,
            (name, properties_json),
        )
        conn.commit()
    finally:
        conn.close()

    return jsonify({"status": "Product with the given name was updated"}), 200


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
